typedef int (*threat_pred)(const void *elem, void *ctx);

size_t threats_filter(const struct threat *in, size_t n, threat_pred keep,
                      void *ctx, struct threat *out, size_t cap) {
    size_t m = 0;
    for (size_t i = 0; i < n && m < cap; i++)
        if (keep(&in[i], ctx)) out[m++] = in[i];   /* copy, never alias */
    return m;
}
